// Données embarquées du modèle 3D glTF/GLB (house.glb)
// Encodage base64 direct pour éliminer 100% des erreurs réseau, de CORS ou d'iframe
export const HOUSE_MODEL_DATA_URI = 'data:model/gltf-binary;base64,';

let cachedBlobUrl: string | null = null;

export function getHouseModelUrl(): string {
  if (typeof window === 'undefined') return HOUSE_MODEL_DATA_URI;
  if (cachedBlobUrl) return cachedBlobUrl;
  try {
    const byteCharacters = atob('');
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: 'model/gltf-binary' });
    cachedBlobUrl = URL.createObjectURL(blob);
    return cachedBlobUrl;
  } catch (e) {
    return HOUSE_MODEL_DATA_URI;
  }
}
